#define MAX 10000

typedef struct {
    int key;
    int count;
} HashNode;

HashNode hash[MAX];
int hashSize = 0;

int findIndex(int key) {
    for (int i = 0; i &lt; hashSize; i++) {
        if (hash[i].key == key) return i;
    }
    return -1;
}

int main() {
    int n1, n2;
    scanf("%d", &n1);
    int nums1[n1];
    for (int i = 0; i &lt; n1; i++) scanf("%d", &nums1[i]);

    scanf("%d", &n2);
    int nums2[n2];
    for (int i = 0; i &lt; n2; i++) scanf("%d", &nums2[i]);

    // Count frequency of nums1
    for (int i = 0; i &lt; n1; i++) {
        int idx = findIndex(nums1[i]);
        if (idx == -1) hash[hashSize++] = (HashNode){nums1[i], 1};
        else hash[idx].count++;
    }

    // Find intersection with nums2
    printf("Intersection: ");
    for (int i = 0; i &lt; n2; i++) {
        int idx = findIndex(nums2[i]);
        if (idx != -1 &amp;&amp; hash[idx].count &gt; 0) {
            printf("%d ", nums2[i]);
            hash[idx].count--;
        }
    }
    printf("\n");

    return 0;
}

int** transpose(int** matrix, int matrixSize, int* matrixColSize, int* returnSize, int** returnColumnSizes) {
    int m = matrixSize;
    int n = matrixColSize[0];

    returnSize = n;
    returnColumnSizes = (int)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        (returnColumnSizes)[i] = m;
    }

    int result = (int*)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        result[i] = (int*)malloc(m * sizeof(int));
    }

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            result[j][i] = matrix[i][j];
        }
    }

    return result;
}

bool isToeplitzMatrix(int** matrix, int matrixSize, int* matrixColSize) {

    int m = matrixSize;
    int n = matrixColSize[0];

    for (int i = 1; i < m; i++) {
        for (int j = 1; j < n; j++) {
            if (matrix[i][j] != matrix[i - 1][j - 1]) {
                return false;
            }
        }
    }

    return true;
}

int* spiralOrder(int** matrix, int matrixSize, int* matrixColSize, int* returnSize) {
    if (matrixSize == 0 || matrixColSize[0] == 0) {
        returnSize = 0;
        return NULL;
    }

    int m = matrixSize;
    int n = matrixColSize[0];
    int result = (int*)malloc(sizeof(int) * m * n);
    int index = 0;

    int top = 0, bottom = m - 1;
    int left = 0, right = n - 1;

    while (top <= bottom && left <= right) {
        for (int i = left; i <= right; i++)
            result[index++] = matrix[top][i];
        top++;

        for (int i = top; i <= bottom; i++)
            result[index++] = matrix[i][right];
        right--;

        if (top <= bottom) {
            for (int i = right; i >= left; i--)
                result[index++] = matrix[bottom][i];
            bottom--;
        }

        if (left <= right) {
            for (int i = bottom; i >= top; i--)
                result[index++] = matrix[i][left];
            left++;
        }
    }

    *returnSize = index;
    return result;
}

void rotate(int** matrix, int matrixSize, int* matrixColSize) {
    int n = matrixSize;

    // Transpose the matrix
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            int temp = matrix[i][j];
            matrix[i][j] = matrix[j][i];
            matrix[j][i] = temp;
        }
    }

    // Reverse each row
    for (int i = 0; i < n; i++) {
        int left = 0, right = n - 1;
        while (left < right) {
            int temp = matrix[i][left];
            matrix[i][left] = matrix[i][right];
            matrix[i][right] = temp;
            left++;
            right--;
        }
    }
}

#include &lt;stdio.h&gt;

void setZeroes(int matrix[200][200], int m, int n) {
    int firstRowZero = 0;
    int firstColZero = 0;

    // Check first column
    for (int i = 0; i < m; i++) {
        if (matrix[i][0] == 0) {
            firstColZero = 1;
            break;
        }
    }

    // Check first row
    for (int j = 0; j < n; j++) {
        if (matrix[0][j] == 0) {
            firstRowZero = 1;
            break;
        }
    }

    // Mark rows and columns
    for (int i = 1; i < m; i++) {
        for (int j = 1; j < n; j++) {
            if (matrix[i][j] == 0) {
                matrix[i][0] = 0;
                matrix[0][j] = 0;
            }
        }
    }

    // Zero rows
    for (int i = 1; i < m; i++) {
        if (matrix[i][0] == 0) {
            for (int j = 1; j < n; j++) {
                matrix[i][j] = 0;
            }
        }
    }

    // Zero columns
    for (int j = 1; j < n; j++) {
        if (matrix[0][j] == 0) {
            for (int i = 1; i < m; i++) {
                matrix[i][j] = 0;
            }
        }
    }

    // Zero first column
    if (firstColZero) {
        for (int i = 0; i < m; i++) {
            matrix[i][0] = 0;
        }
    }

    // Zero first row
    if (firstRowZero) {
        for (int j = 0; j < n; j++) {
            matrix[0][j] = 0;
        }
    }
}

void reverse(int* nums, int start, int end) {
    while (start < end) {
        int temp = nums[start];
        nums[start] = nums[end];
        nums[end] = temp;
        start++;
        end--;
    }
}

void rotate(int* nums, int numsSize, int k) {
    if (numsSize == 0) return;

    k = k % numsSize;   // handle k > size

    reverse(nums, 0, numsSize - 1);      // reverse whole array
    reverse(nums, 0, k - 1);             // reverse first k elements
    reverse(nums, k, numsSize - 1);      // reverse remaining elements
}

int maxSubArray(int* nums, int numsSize) {
    int maxSum = nums[0];
    int currSum = nums[0];

    for (int i = 1; i < numsSize; i++) {
        if (currSum < 0)
            currSum = nums[i];
        else
            currSum += nums[i];

        if (currSum > maxSum)
            maxSum = currSum;
    }

    return maxSum;
}

int* productExceptSelf(int* nums, int numsSize, int* returnSize) {
    int* answer = (int*)malloc(numsSize * sizeof(int));

    *returnSize = numsSize;

    // Step 1: Prefix products
    answer[0] = 1;
    for (int i = 1; i < numsSize; i++) {
        answer[i] = answer[i - 1] * nums[i - 1];
    }

    // Step 2: Suffix products
    int suffix = 1;
    for (int i = numsSize - 1; i >= 0; i--) {
        answer[i] = answer[i] * suffix;
        suffix *= nums[i];
    }

    return answer;
}

int maxSubarraySumCircular(int* nums, int numsSize) {
    int totalSum = 0;
    int maxSub = nums[0], currentMax = nums[0];
    int minSub = nums[0], currentMin = nums[0];

    for (int i = 0; i < numsSize; i++) {
        totalSum += nums[i];
        if (i > 0) {
            currentMax = (nums[i] > currentMax + nums[i]) ? nums[i] : currentMax + nums[i];
            maxSub = (maxSub > currentMax) ? maxSub : currentMax;

            currentMin = (nums[i] < currentMin + nums[i]) ? nums[i] : currentMin + nums[i];
            minSub = (minSub < currentMin) ? minSub : currentMin;
        }
    }

    if (totalSum == minSub) return maxSub;

    int circularMax = totalSum - minSub;
    return (maxSub > circularMax) ? maxSub : circularMax;
}

