struct TreeNode* lowestCommonAncestor(struct TreeNode* root, struct TreeNode* p, struct TreeNode* q) {
    while(root != NULL) {
        if(p-&gt;val &lt; root-&gt;val &amp;&amp; q-&gt;val &lt; root-&gt;val)
            root = root-&gt;left;
        else if(p-&gt;val &gt; root-&gt;val &amp;&amp; q-&gt;val &gt; root-&gt;val)
            root = root-&gt;right;
        else
            return root;
    }
    return NULL;
}

struct TreeNode* lowestCommonAncestor(struct TreeNode* root, struct TreeNode* p, struct TreeNode* q) {
    if(root == NULL || root == p || root == q)
        return root;

    struct TreeNode* left = lowestCommonAncestor(root-&gt;left, p, q);
    struct TreeNode* right = lowestCommonAncestor(root-&gt;right, p, q);

    if(left != NULL &amp;&amp; right != NULL)
        return root;

    if(left != NULL)
        return left;

    return right;
}

int** levelOrder(struct TreeNode* root, int* returnSize, int** returnColumnSizes) {
    *returnSize = 0;
    if(root == NULL) {
        *returnColumnSizes = NULL;
        return NULL;
    }

    int** ans = (int**)malloc(1000 * sizeof(int*));
    *returnColumnSizes = (int*)malloc(1000 * sizeof(int));

    struct TreeNode* q[1000];
    int front = 0, rear = 0;
    q[rear++] = root;

    while(front &lt; rear) {
        int size = rear - front;
        ans[*returnSize] = (int*)malloc(size * sizeof(int));
        (*returnColumnSizes)[*returnSize] = size;

        for(int i = 0; i &lt; size; i++) {
            struct TreeNode* node = q[front++];
            ans[*returnSize][i] = node-&gt;val;

            if(node-&gt;left) q[rear++] = node-&gt;left;
            if(node-&gt;right) q[rear++] = node-&gt;right;
        }

        (*returnSize)++;
    }

    return ans;
}

int** zigzagLevelOrder(struct TreeNode* root, int* returnSize, int** returnColumnSizes) {
    *returnSize = 0;
    if(root == NULL) {
        *returnColumnSizes = NULL;
        return NULL;
    }

    int** ans = (int**)malloc(1000 * sizeof(int*));
    *returnColumnSizes = (int*)malloc(1000 * sizeof(int));

    struct TreeNode* q[1000];
    int front = 0, rear = 0;
    q[rear++] = root;
    int leftToRight = 1;

    while(front &lt; rear) {
        int size = rear - front;
        ans[*returnSize] = (int*)malloc(size * sizeof(int));
        (*returnColumnSizes)[*returnSize] = size;

        for(int i = 0; i &lt; size; i++) {
            struct TreeNode* node = q[front++];
            int index;

            if(leftToRight)
                index = i;
            else
                index = size - i - 1;

            ans[*returnSize][index] = node-&gt;val;

            if(node-&gt;left) q[rear++] = node-&gt;left;
            if(node-&gt;right) q[rear++] = node-&gt;right;
        }

        leftToRight = !leftToRight;
        (*returnSize)++;
    }

    return ans;
}

int* rightSideView(struct TreeNode* root, int* returnSize) {
    *returnSize = 0;
    if(root == NULL) return NULL;

    int* ans = (int*)malloc(1000 * sizeof(int));
    struct TreeNode* q[1000];
    int front = 0, rear = 0;
    q[rear++] = root;

    while(front &lt; rear) {
        int size = rear - front;

        for(int i = 0; i &lt; size; i++) {
            struct TreeNode* node = q[front++];

            if(i == size - 1)
                ans[(*returnSize)++] = node-&gt;val;

            if(node-&gt;left) q[rear++] = node-&gt;left;
            if(node-&gt;right) q[rear++] = node-&gt;right;
        }
    }

    return ans;
}

bool isMirror(struct TreeNode* left, struct TreeNode* right) {
    if(left == NULL &amp;&amp; right == NULL)
        return true;

    if(left == NULL || right == NULL)
        return false;

    if(left-&gt;val != right-&gt;val)
        return false;

    return isMirror(left-&gt;left, right-&gt;right) &amp;&amp; isMirror(left-&gt;right, right-&gt;left);
}

bool isSymmetric(struct TreeNode* root) {
    if(root == NULL)
        return true;
    return isMirror(root-&gt;left, root-&gt;right);
}

void flatten(struct TreeNode* root) {
    if(root == NULL)
        return;

    flatten(root-&gt;left);
    flatten(root-&gt;right);

    struct TreeNode* left = root-&gt;left;
    struct TreeNode* right = root-&gt;right;

    root-&gt;left = NULL;
    root-&gt;right = left;

    struct TreeNode* curr = root;
    while(curr-&gt;right != NULL)
        curr = curr-&gt;right;

    curr-&gt;right = right;
}

struct TreeNode* build(int preorder[], int inorder[], int inStart, int inEnd, int* preIndex) {
    if(inStart &gt; inEnd)
        return NULL;

    int val = preorder[*preIndex];
    (*preIndex)++;

    struct TreeNode* root = (struct TreeNode*)malloc(sizeof(struct TreeNode));
    root-&gt;val = val;
    root-&gt;left = NULL;
    root-&gt;right = NULL;

    if(inStart == inEnd)
        return root;

    int index;
    for(index = inStart; index &lt;= inEnd; index++) {
        if(inorder[index] == val)
            break;
    }

    root-&gt;left = build(preorder, inorder, inStart, index - 1, preIndex);
    root-&gt;right = build(preorder, inorder, index + 1, inEnd, preIndex);

    return root;
}

struct TreeNode* build(int inorder[], int postorder[], int inStart, int inEnd, int* postIndex) {
    if(inStart &gt; inEnd)
        return NULL;

    int val = postorder[*postIndex];
    (*postIndex)--;

    struct TreeNode* root = (struct TreeNode*)malloc(sizeof(struct TreeNode));
    root-&gt;val = val;
    root-&gt;left = NULL;
    root-&gt;right = NULL;

    if(inStart == inEnd)
        return root;

    int index;
    for(index = inStart; index &lt;= inEnd; index++) {
        if(inorder[index] == val)
            break;
    }

    root-&gt;right = build(inorder, postorder, index + 1, inEnd, postIndex);
    root-&gt;left = build(inorder, postorder, inStart, index - 1, postIndex);

    return root;
}

int cameras;

int dfs(struct TreeNode* root) {
    if(root == NULL)
        return 1;

    int left = dfs(root-&gt;left);
    int right = dfs(root-&gt;right);

    if(left == 2 || right == 2) {
        cameras++;
        return 0;
    }

    if(left == 0 || right == 0)
        return 1;

    return 2;
}

int minCameraCover(struct TreeNode* root) {
    cameras = 0;
    if(dfs(root) == 2)
        cameras++;
    return cameras;
}

