class Solution {
public:
    bool canVisitAllRooms(vector&lt;vector&lt;int&gt;&gt;&amp; rooms) {
        int n = rooms.size();
        vector&lt;bool&gt; visited(n, false);
        visited[0] = true;
        vector&lt;int&gt; stack;
        stack.push_back(0);

        while(!stack.empty()){
            int current = stack.back();
            stack.pop_back();

            for(int key : rooms[current]){
                if(!visited[key]){
                    visited[key] = true;
                    stack.push_back(key);
                }
            }
        }

        for(bool v : visited){
            if(!v) return false;
        }
        return true;
    }
};

