int solve(int mask, int pos, int n, int cost[][20]) {

    if(mask == (1 &lt;&lt; n) - 1)
        return cost[pos][0];

    if(dp[pos][mask] != -1)
        return dp[pos][mask];

    int ans = INT_MAX;

    for(int city = 0; city &lt; n; city++) {
        if((mask &amp; (1 &lt;&lt; city)) == 0) {

            int newAns = cost[pos][city] +
                         solve(mask | (1 &lt;&lt; city), city, n, cost);

            ans = min(ans, newAns);
        }
    }

    return dp[pos][mask] = ans;
}

