/**
 * Return an array of arrays of size *returnSize.
 * The sizes of the arrays are returned as *returnColumnSizes array.
 * Note: Both returned array and *columnSizes array must be malloced, assume caller calls free().
 */

typedef struct Node {
    int v;
    struct Node* next;
} Node;

int timer;

Node* addEdge(Node* head, int v) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode-&gt;v = v;
    newNode-&gt;next = head;
    return newNode;
}

void dfs(int node, int parent, Node** adj, int* visited, int* disc, int* low,
         int** ans, int* count, int** returnColumnSizes) {
    visited[node] = 1;
    disc[node] = low[node] = timer++;

    Node* temp = adj[node];
    while(temp != NULL) {
        int next = temp-&gt;v;

        if(next == parent) {
            temp = temp-&gt;next;
            continue;
        }

        if(!visited[next]) {
            dfs(next, node, adj, visited, disc, low, ans, count, returnColumnSizes);

            if(low[next] &lt; low[node])
                low[node] = low[next];

            if(low[next] &gt; disc[node]) {
                ans[*count] = (int*)malloc(2 * sizeof(int));
                ans[*count][0] = node;
                ans[*count][1] = next;
                (*returnColumnSizes)[*count] = 2;
                (*count)++;
            }
        }
        else {
            if(disc[next] &lt; low[node])
                low[node] = disc[next];
        }

        temp = temp-&gt;next;
    }
}

int** criticalConnections(int n, int** connections, int connectionsSize, int* connectionsColSize, int* returnSize, int** returnColumnSizes) {
    Node** adj = (Node**)malloc(n * sizeof(Node*));
    for(int i = 0; i &lt; n; i++) {
        adj[i] = NULL;
    }

    for(int i = 0; i &lt; connectionsSize; i++) {
        int u = connections[i][0];
        int v = connections[i][1];
        adj[u] = addEdge(adj[u], v);
        adj[v] = addEdge(adj[v], u);
    }

    int* visited = (int*)calloc(n, sizeof(int));
    int* disc = (int*)malloc(n * sizeof(int));
    int* low = (int*)malloc(n * sizeof(int));

    int** ans = (int**)malloc(connectionsSize * sizeof(int*));
    *returnColumnSizes = (int*)malloc(connectionsSize * sizeof(int));
    *returnSize = 0;
    timer = 0;

    for(int i = 0; i &lt; n; i++) {
        if(!visited[i]) {
            dfs(i, -1, adj, visited, disc, low, ans, returnSize, returnColumnSizes);
        }
    }

    free(visited);
    free(disc);
    free(low);

    for(int i = 0; i &lt; n; i++) {
        Node* temp = adj[i];
        while(temp != NULL) {
            Node* next = temp-&gt;next;
            free(temp);
            temp = next;
        }
    }
    free(adj);

    return ans;
}

int timer;

void dfsAP(int node, int parent, int visited[], int disc[], int low[], int mark[], int adj[105][105], int n) {
    visited[node] = 1;
    disc[node] = low[node] = timer++;
    int child = 0;

    for(int v = 0; v &lt; n; v++) {
        if(adj[node][v] == 0)
            continue;

        if(v == parent)
            continue;

        if(!visited[v]) {
            dfsAP(v, node, visited, disc, low, mark, adj, n);
            if(low[v] &lt; low[node])
                low[node] = low[v];

            if(low[v] &gt;= disc[node] &amp;&amp; parent != -1)
                mark[node] = 1;

            child++;
        }
        else {
            if(disc[v] &lt; low[node])
                low[node] = disc[v];
        }
    }

    if(parent == -1 &amp;&amp; child &gt; 1)
        mark[node] = 1;
}

