    while(low &lt;= high) {
        int mid = low + (high - low) / 2;

        if(nums[mid] &gt;= target) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }

    return ans;
}

int search(int* nums, int numsSize, int target) {
    int low = 0, high = numsSize - 1;

    while(low &lt;= high) {
        int mid = low + (high - low) / 2;

        if(nums[mid] == target)
            return mid;

        /* Left half is sorted */
        if(nums[low] &lt;= nums[mid]) {
            if(target &gt;= nums[low] &amp;&amp; target &lt; nums[mid])
                high = mid - 1;
            else
                low = mid + 1;
        }
        /* Right half is sorted */
        else {
            if(target &gt; nums[mid] &amp;&amp; target &lt;= nums[high])
                low = mid + 1;
            else
                high = mid - 1;
        }
    }

    return -1;
}

int findPeakElement(int* nums, int numsSize) {
    int low = 0, high = numsSize - 1;

    while(low &lt; high) {
        int mid = low + (high - low) / 2;

        if(nums[mid] &gt; nums[mid + 1])
            high = mid;
        else
            low = mid + 1;
    }

    return low;
}

int findMin(int* nums, int numsSize) {
    int low = 0, high = numsSize - 1;

    while(low &lt; high) {
        int mid = low + (high - low) / 2;

        if(nums[mid] &gt; nums[high])
            low = mid + 1;
        else
            high = mid;
    }

    return nums[low];
}

int mySqrt(int x) {
    if(x == 0) return 0;

    int low = 1, high = x;
    int ans = 0;

    while(low &lt;= high) {
        long long mid = low + (high - low) / 2;

        if(mid * mid &lt;= (long long)x) {
            ans = (int)mid;
            low = (int)mid + 1;
        } else {
            high = (int)mid - 1;
        }
    }

    return ans;
}

