int canPlace(int* pos, int n, int m, int minDist) {
    int count = 1;
    int lastPos = pos[0];

    for(int i = 1; i &lt; n; i++) {
        if(pos[i] - lastPos &gt;= minDist) {
            count++;
            lastPos = pos[i];
        }

        if(count &gt;= m)
            return 1;
    }

    return 0;
}

int maxDistance(int* position, int positionSize, int m) {
    qsort(position, positionSize, sizeof(int), compare);

    int low = 1;
    int high = position[positionSize - 1] - position[0];
    int ans = 0;

    while(low &lt;= high) {
        int mid = low + (high - low) / 2;

        if(canPlace(position, positionSize, m, mid)) {
            ans = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }

    return ans;
}

void findMaxNSum(int* weights, int size, int* low, int* high) {
    for (int i = 0; i &lt; size; i++) {
        if (*low &gt; weights[i]) *low = weights[i];
        *high += weights[i];
    }
}

bool findMinWeights(int* weights, int size, int days, int minWeight) {
    int temp = minWeight;
    int i = 0;
    while (i &lt; size &amp;&amp; days &gt; 0) {
        if (temp &lt; weights[i]) {
            days--;
            temp = minWeight;
        } else {
            temp -= weights[i];
            i++;
        }
    }
    return i == size;
}

int shipWithinDays(int* weights, int weightsSize, int days) {
    int low = 0, high = 0, ans = 0;
    findMaxNSum(weights, weightsSize, &amp;low, &amp;high);
    while (low &lt;= high) {
        int mid = (low + high) / 2;
        if (findMinWeights(weights, weightsSize, days, mid)) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    return ans;
}

int canSplit(int* nums, int n, int k, int maxSum) {
    int parts = 1;
    int currentSum = 0;

    for(int i = 0; i &lt; n; i++) {
        if(currentSum + nums[i] &gt; maxSum) {
            parts++;
            currentSum = nums[i];

            if(parts &gt; k)
                return 0;
        } else {
            currentSum += nums[i];
        }
    }

    return 1;
}

int splitArray(int* nums, int numsSize, int k) {
    int low = 0, high = 0;

    for(int i = 0; i &lt; numsSize; i++) {
        if(nums[i] &gt; low)
            low = nums[i];
        high += nums[i];
    }

    int ans = high;

    while(low &lt;= high) {
        int mid = low + (high - low) / 2;

        if(canSplit(nums, numsSize, k, mid)) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }

    return ans;
}

