void swap(int* nums, int i, int j) {
    int temp = nums[i];
    nums[i] = nums[j];
    nums[j] = temp;
}

int partition(int* nums, int low, int high) {
    int pivot = nums[low];
    int j = low;

    for (int i = low + 1; i <= high; i++) {
        if (nums[i] < pivot) {
            j++;
            swap(nums, i, j);
        }
    }
    swap(nums, low, j);
    return j;
}

int QSelect(int* nums, int low, int high, int k) {
    if (low <= high) {
        int p = partition(nums, low, high);

        if (p == k) return nums[p];
        if (p < k) return QSelect(nums, p + 1, high, k);
        else return QSelect(nums, low, p - 1, k);
    }
    return nums[low];
}

int findKthLargest(int* nums, int numsSize, int k) {
    return QSelect(nums, 0, numsSize - 1, numsSize - k);
}

struct ListNode* insertionSortList(struct ListNode* head) {
    if (!head || !head->next) {
        return head;
    }

    struct ListNode* dummy = malloc(sizeof(struct ListNode));
    dummy->next = head;

    struct ListNode* prev = head;
    struct ListNode* cur = head->next;

    while (cur) {
        if (prev->val <= cur->val) {
            prev = cur;
            cur = cur->next;
        } else {
            struct ListNode* temp = dummy;

            while (cur->val > temp->next->val)
                temp = temp->next;

            prev->next = cur->next;
            cur->next = temp->next;
            temp->next = cur;

            cur = prev->next;
        }
    }
    return dummy->next;
}

int* relativeSortArray(int* arr1,int arr1Size,int* arr2,int arr2Size,int* returnSize){
    int* result=(int*)malloc(sizeof(int)*arr1Size);
    int idx=0;

    for(int i=0;i<arr2Size;i++){
        int x=arr2[i];
        for(int j=0;j<arr1Size;j++){
            if(arr1[j]==x){
                result[idx++]=x;
            }
        }
    }

    int start=idx;

    for(int i=0;i<arr1Size;i++){
        int found=0;
        for(int j=0;j<arr2Size;j++){
            if(arr1[i]==arr2[j]){
                found=1;
                break;
            }
        }
        if(!found){
            result[idx++]=arr1[i];
        }
    }

    for(int i=start;i<arr1Size;i++){
        for(int j=i+1;j<arr1Size;j++){
            if(result[i]>result[j]){
                int tmp=result[i];
                result[i]=result[j];
                result[j]=tmp;
            }
        }
    }

    *returnSize=arr1Size;
    return result;
}

