int countWhileMerge(int* nums, int left, int mid, int right) {
    int count = 0;
    int j = mid + 1;
    for (int i = left; i <= mid; i++) {
        while (j <= right && (long long)nums[i] > 2LL * nums[j]) j++;
        count += (j - (mid + 1));
    }
    return count;
}

void merge(int* nums, int left, int mid, int right) {
    int n = right - left + 1;
    int* temp = (int*)malloc(n * sizeof(int));
    int i = left, j = mid + 1, k = 0;

    while (i <= mid && j <= right) {
        if (nums[i] <= nums[j]) temp[k++] = nums[i++];
        else temp[k++] = nums[j++];
    }
    while (i <= mid) temp[k++] = nums[i++];
    while (j <= right) temp[k++] = nums[j++];

    for (i = 0; i < n; i++) nums[left + i] = temp[i];
    free(temp);
}

int mergeSort(int* nums, int left, int right) {
    if (left >= right) return 0;
    int mid = left + (right - left) / 2;

    int count = mergeSort(nums, left, mid);
    count += mergeSort(nums, mid + 1, right);
    count += countWhileMerge(nums, left, mid, right);

    merge(nums, left, mid, right);
    return count;
}

int minMeetingRooms(int** intervals, int intervalsSize) {
    if (intervalsSize == 0) return 0;

    int* start = (int*)malloc(intervalsSize * sizeof(int));
    int* end = (int*)malloc(intervalsSize * sizeof(int));

    for (int i = 0; i < intervalsSize; i++) {
        start[i] = intervals[i][0];
        end[i] = intervals[i][1];
    }

    qsort(start, intervalsSize, sizeof(int), (__compar_fn_t)strcmp);
    qsort(end, intervalsSize, sizeof(int), (__compar_fn_t)strcmp);

    int rooms = 0, endPtr = 0;
    for (int i = 0; i < intervalsSize; i++) {
        if (start[i] < end[endPtr]) rooms++;
        else endPtr++;
    }

    free(start);
    free(end);
    return rooms;
}

