int* BIT;
int size;

void update(int i) {
    while (i <= size) {
        BIT[i] += 1;
        i += (i & -i);
    }
}

int query(int i) {
    int sum = 0;
    while (i > 0) {
        sum += BIT[i];
        i -= (i & -i);
    }
    return sum;
}

